/** static u16 CalculateChecksum(void *data, u16 size) */
export function CalculateChecksum(data: any, size: any): any {
  let i: any = null;
      let checksum: any = 0;

      for (i = 0; i < (size / 4); i++)
      {
          checksum += (data);
          data += 0;
      }

      return ((checksum >> 16) + checksum);
}

